{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 8,
      "verse": 11,
      "text_ar": "لِيُطَعَّمَ الجَسَدُ الَّذِي صُنِعَ لَحِينًا، وَبَعْدَ ذَلِكَ تَهْدِيْهِ فِي رَحْمَتِكَ."
    },
    {
      "chapter": 8,
      "verse": 12,
      "text_ar": "نَعَمْ، أَنْتَ رَفَعْتَهُ فِي صِدْقِكَ، وَرَبَّيْتَهُ فِي شَرِيعَتِكَ، وَصَحَّحْتَهُ بِحُكْمِكَ."
    },
    {
      "chapter": 8,
      "verse": 13,
      "text_ar": "أَنْتَ قَتَلْتَهُ كَخَلْقِكَ، وَجَعَلْتَهُ يَحْيَى كَعَمَلِكَ."
    },
    {
      "chapter": 8,
      "verse": 14,
      "text_ar": "فَإِنْ كُنتَ تَدْمِرُهُ بِسُهُولَةٍ وَفَجْأَةٍ الَّذِي صُنِعَ بِجِهْدٍ عَظِيمٍ بِأَمْرِكَ، فَمَا هَدَفُ خَلْقِهِ؟"
    },
    {
      "chapter": 8,
      "verse": 15,
      "text_ar": "الآنَ إذًا سَأَتَكَلَّمُ. عَنِ الإِنْسَانِ عُمُومًا أَنتَ أَعْلَمُ، وَلَكِنْ عَنِ شَعْبِكَ الَّذِي أَشْعُرُ لَهُ بِالْحُزْنِ،"
    },
    {
      "chapter": 8,
      "verse": 16,
      "text_ar": "وَعَنِ مِيرَاثِكَ الَّذِي أَنَا أَبْكِي مِنْ أجْلِهِ، عَنِ إِسْرَائِيلَ الَّذِي أَحْمِلُهُ فِي كُثْرَةِ الثِّقَلِ، وَعَنِ بُذْرِ يَعْقُوبَ الَّذِي أَشْعُرُ بِالْقَلَقِ مِنْ أجْلِهِ،"
    },
    {
      "chapter": 8,
      "verse": 17,
      "text_ar": "لِذَلِكَ سَأَبْدَأُ أَدْعُو إِلَيْكَ لِنَفْسِي وَلَهُمْ؛ لأَنِّي أَرَى عُيُوبَ الَّذِينَ يَسْكُنُونَ فِي الأَرْضِ؛"
    },
    {
      "chapter": 8,
      "verse": 18,
      "text_ar": "وَلَكِنْ سَمِعْتُ سُرْعَةَ الْحُكْمِ الَّذِي سَيَأْتِي."
    },
    {
      "chapter": 8,
      "verse": 19,
      "text_ar": "إِذًا اسْمَعْ صَوْتِي، وَافْهَمْ قَوْلِي، وَسَأَتَكَلَّمُ أَمَامَكَ. بَدْءُ كَلِمَاتِ عِزْرَا، قَبْلَ أَنْ يُرْتَفَعَ إِلَيْهِ. قَالَ،"
    },
    {
      "chapter": 8,
      "verse": 20,
      "text_ar": "يا رَبُّ، أَنْتَ الَّذِي تَبْقَى إِلَى الأَبَدِ، وَعَيْنَاكَ رَافِعَةٌ، وَغُرَفُكَ فِي السَّمَاءِ."
    }
  ]
}
